import { prisma } from "@/lib/db";
import { absoluteUrl } from "@/lib/server/app-url";

/**
 * Согласие на обработку персональных данных в мессенджере (§7).
 *
 * Раздел настроек хранил текст и версию согласия, но спросить его было
 * некому: ни одной строки PatientConsent платформа не создавала никогда, а
 * агент про согласие не говорил ни слова. Для клиники, работающей с
 * медицинскими данными в России, это не косметика — 152-ФЗ требует
 * зафиксированного согласия до обработки.
 *
 * Спрашиваем один раз за диалог, при первом обращении. Карточки пациента в
 * этот момент может ещё не быть, поэтому факт живёт на диалоге и переносится
 * в PatientConsent, как только карточка появится.
 */

export const CONSENT_ACCEPT = "consent:yes";
export const CONSENT_DECLINE = "consent:no";

export interface ConsentRequest {
  text: string;
  buttons: { text: string; data: string }[];
}

/**
 * Нужно ли спросить согласие прямо сейчас. Возвращает готовое сообщение или
 * null, если спрашивать не нужно: согласие уже дано, вопрос уже задан или
 * клиника не завела текст согласия.
 */
export async function consentRequestFor(
  companyId: string,
  conversationId: string,
  /**
   * Спрашивать ли согласие, если его ещё нет.
   *
   * `false` — только разобраться с уже данным: узнать своего пациента и
   * перенести отметку из карточки. Нужно потому, что согласие спрашивается не
   * при первом «здравствуйте», а перед запросом персональных данных (решение
   * заказчика, сентябрь 2026, — так написано и в его инструкции ассистенту).
   * Раньше вопрос стоял стеной на входе: человек спрашивал цену и первым, что
   * слышал от клиники, был юридический текст.
   */
  ask = true,
): Promise<ConsentRequest | null> {
  const conv = await prisma.conversation.findUnique({
    where: { id: conversationId },
    select: { consentAskedAt: true, consentGrantedAt: true, patientId: true },
  });
  if (!conv || conv.consentGrantedAt) return null;

  /**
   * Клиника уже знает этого человека — проверяем ДО всего остального.
   *
   * Раньше здесь стоял выход по `consentAskedAt`: спросили один раз — больше
   * не спрашиваем. Выглядело разумно, а на деле запирало диалог навсегда.
   * Пациентка ходит в клинику с июля, переписывается с администратором, была
   * на приёме — и получила запрос согласия. Не ответила «да» (она писала
   * благодарность врачу, а не заполняла форму), и с тех пор КАЖДОЕ её
   * сообщение упиралось в одну и ту же стену: «нужно ваше согласие». Через
   * три недели она спросила про свободное окно — и снова получила стену.
   *
   * Проверка «клиника её знает» стояла ниже и до неё дело не доходило.
   * Теперь она первая: у человека с визитами и месяцем переписки согласие
   * взято на приёме, и требовать его в мессенджере — значит не узнавать
   * своего пациента.
   */
  if (await knownToClinic(companyId, conversationId, conv.patientId)) {
    const now = new Date();
    await prisma.conversation.update({
      where: { id: conversationId },
      data: { consentGrantedAt: now, consentAskedAt: conv.consentAskedAt ?? now },
    });
    if (conv.patientId) await materializeConsent(companyId, conv.patientId, conversationId);
    return null;
  }

  // Спрашивать не просили — значит только проверяли, есть ли согласие.
  if (!ask) return null;

  // Спросили и ждём ответа — второй раз не спрашиваем.
  if (conv.consentAskedAt) return null;

  /**
   * Согласие принадлежит пациенту, а не переписке.
   *
   * Оно хранилось только на диалоге, и постоянная пациентка, написавшая с
   * другого канала или в новом диалоге, получала требование согласиться
   * заново — хотя подписала его давно и ходит в клинику годами. Для неё это
   * выглядит так, будто её не помнят.
   *
   * Если карточка привязана и согласие в ней есть — переносим отметку на
   * диалог и молчим.
   */
  if (conv.patientId) {
    const given = await prisma.patientConsent.findFirst({
      where: { companyId, patientId: conv.patientId },
      select: { grantedAt: true },
    });
    if (given) {
      await prisma.conversation.update({
        where: { id: conversationId },
        data: { consentGrantedAt: given.grantedAt, consentAskedAt: given.grantedAt },
      });
      return null;
    }
  }

  const doc = await prisma.consentDocument.findFirst({
    where: { companyId, isActive: true },
    orderBy: { createdAt: "desc" },
    select: { policyUrl: true },
  });

  /**
   * Куда вести пациента за текстом.
   *
   * Ведём на свою страницу /policy — решение заказчика: документ живёт в
   * платформе и участвует в переписке. Ссылка на чужой файлообменник может
   * перестать открываться в любой день, и тогда согласие нельзя ни дать, ни
   * подтвердить, а без него §7 не разрешает вести переписку.
   *
   * Ссылка из настроек остаётся запасной — на случай, когда домен ещё не
   * задан (например, на локальном стенде).
   */
  const policyUrl = absoluteUrl("/policy") || doc?.policyUrl?.trim() || null;
  if (!policyUrl) return null;

  await prisma.conversation.update({
    where: { id: conversationId },
    data: { consentAskedAt: new Date() },
  });

  return {
    text:
      /**
       * Согласие просят ровно под то, ради чего оно нужно, — под запись.
       *
       * Прежде здесь стояло «чтобы отвечать на вопросы и записывать вас на
       * приём». Это осталось от той поры, когда согласие спрашивали на входе
       * и без него не шла вся переписка. Теперь справочные вопросы — часы,
       * адрес, прайс — агент отвечает свободно (§7), и упоминание вопросов
       * стало неправдой: человек читает, что без согласия ему не ответят, и
       * это отпугивает там, где отпугивать нечем.
       */
      "Прежде чем продолжить: чтобы записывать вас на приём, " +
      "нам нужно ваше согласие на обработку персональных данных.\n" +
      `Политика: ${policyUrl}`,
    buttons: [
      { text: "Согласен(на)", data: CONSENT_ACCEPT },
      { text: "Не сейчас", data: CONSENT_DECLINE },
    ],
  };
}

/**
 * Насколько давним должно быть сообщение сотрудника, чтобы считаться прошлой
 * перепиской. Текущее обращение уже сохранено к моменту проверки, и без окна
 * оно засчитало бы само себя.
 */
const PRIOR_TALK_MS = 10 * 60 * 1000;

/**
 * Клиника уже знает этого человека: есть визиты или переписка до сегодня.
 */
async function knownToClinic(
  companyId: string,
  conversationId: string,
  patientId: string | null,
): Promise<boolean> {
  if (patientId) {
    const visits = await prisma.appointment.count({
      where: { companyId, patientId, deletedAt: null },
    });
    if (visits > 0) return true;
  }

  /**
   * Согласие в карточке — самый прямой признак: человек его уже давал.
   */
  if (patientId) {
    const given = await prisma.patientConsent.findFirst({
      where: { companyId, patientId },
      select: { id: true },
    });
    if (given) return true;
  }

  /**
   * С человеком разговаривал СОТРУДНИК — значит согласие взято голосом.
   *
   * Здесь стояло «есть любое сообщение старше десяти минут», и это была дыра.
   * Пока согласие спрашивалось на входе, она не проявлялась: второе сообщение
   * приходило уже после вопроса. Но согласие теперь спрашивается перед
   * запросом данных — и новый человек, который двадцать минут спрашивал цены,
   * к моменту записи становился «знакомым клинике», а согласие проставлялось
   * само. Он его не давал.
   *
   * Собственные реплики пациента и ответы бота знакомства не создают.
   * Создаёт его только живой сотрудник: он и берёт согласие на приёме или в
   * разговоре.
   */
  const staffTalked = await prisma.message.count({
    where: {
      conversationId,
      deletedAt: null,
      isDraft: false,
      authorType: "STAFF",
      createdAt: { lt: new Date(Date.now() - PRIOR_TALK_MS) },
    },
  });
  return staffTalked > 0;
}

/**
 * Зафиксировать согласие. Если карточка пациента уже привязана — пишем строку
 * PatientConsent сразу, иначе она появится при привязке.
 */
export async function grantConsent(companyId: string, conversationId: string): Promise<void> {
  const now = new Date();
  const conv = await prisma.conversation.update({
    where: { id: conversationId },
    data: { consentGrantedAt: now },
    select: { patientId: true, channel: true },
  });
  if (conv.patientId) {
    await materializeConsent(companyId, conv.patientId, conversationId);
  }
}

/**
 * Перенести согласие с диалога в карточку пациента. Вызывается, когда карточка
 * появилась: до этого момента привязать согласие было не к кому.
 */
export async function materializeConsent(
  companyId: string,
  patientId: string,
  conversationId: string,
): Promise<void> {
  const [conv, doc] = await Promise.all([
    prisma.conversation.findUnique({
      where: { id: conversationId },
      select: { consentGrantedAt: true, channel: true },
    }),
    prisma.consentDocument.findFirst({
      where: { companyId, isActive: true },
      orderBy: { createdAt: "desc" },
      select: { id: true },
    }),
  ]);
  if (!conv?.consentGrantedAt || !doc) return;

  await prisma.patientConsent
    .upsert({
      where: { patientId_documentId: { patientId, documentId: doc.id } },
      update: {},
      create: {
        companyId,
        patientId,
        documentId: doc.id,
        grantedAt: conv.consentGrantedAt,
        channel: conv.channel,
      },
    })
    .catch(() => {});
}

/**
 * Просьба о согласии в тексте ответа.
 *
 * Согласие ведёт платформа: она спрашивает его один раз и хранит факт в базе.
 * Модель об этом не знает и повторяет просьбу за нами — на живом прогоне
 * пациент ответил «Да», получил приветствие клиники и следом «теперь мне
 * нужно ваше согласие… согласны ли вы?». Разговор закольцевался.
 *
 * Убираем такие предложения ВСЕГДА, а не только когда согласие уже есть.
 * Когда его ещё нет, просьбу задаёт платформа своим текстом со ссылкой на
 * политику — и если оставить рядом формулировку модели, человек получает два
 * разных запроса согласия подряд в одном сообщении: «Пожалуйста, ответьте:
 * „Согласен/Согласна“» и следом «Ответьте „Да“ или „Нет“». Так и было на
 * живом диалоге 11 сентября.
 *
 * Список нарочно шире наших собственных формулировок: модель просит согласие
 * своими словами, и ловить надо её, а не себя. Остальной текст — цена,
 * услуга, вопрос по делу — остаётся.
 *
 * «Согласны на ИХ обработку Клиникой… в соответствии с Политикой ОБРАБОТКИ
 * персональных данных?» проходило насквозь: между «на» и «обработку» стояло
 * слово, а «обработки» — не «обработку». Падеж и вставное слово теперь
 * допускаются.
 *
 * «Вы согласны с тем, что ваши данные будут использованы для записи на приём?»
 * (живой диалог 29 сентября) не совпадало ни с одним шаблоном: ни «обработки»,
 * ни «согласны ли вы». Вопрос ушёл пациенту без ссылки на политику, платформа
 * его своим не считала, и «Да» свайпом повисло без ответа. «Согласны … данные»
 * в одном предложении — это всегда вопрос о согласии: «согласие получено» так
 * не пишут.
 */
const CONSENT_ASK =
  /(?:согласн\p{L}*[^.!?\n]{0,80}(?:данн\p{L}*|использова\p{L}*)|соглас\p{L}*\s+на\s+(?:\p{L}+\s+){0,2}обработк|обработк\p{L}*\s+персональн|обработку\s+персональных\s+данных|согласны\s+ли\s+вы|вы\s+согласн\p{L}*\s*\?|ответьте\s+«?да»?\s+или\s+«?нет»?|(?:ответьте|напишите|отправьте)\s*,?\s*(?:пожалуйста\s*,?\s*)?:?\s*[«"„]?\s*соглас|политик\p{L}*[^.!?\n]{0,60}(?:по\s+ссылке|ссылк\p{L}*\s+выше)|(?:нужн\p{L}*|требуется|необходимо|понадоб\p{L}*)\s+(?:\p{L}+\s+){0,2}соглас|(?:подтвердите|дайте|предоставьте)\s+(?:ваше\s+)?соглас)/iu;

/**
 * В ответе есть просьба о согласии — чьими бы словами она ни была написана.
 *
 * Живой диалог 14 сентября: модель сама написала «Для записи мне нужно Ваше
 * согласие на обработку персональных данных. Вы согласны?» — без ссылки на
 * политику и без отметки в базе, что согласие спрошено. Пациентка ответила
 * «Да», платформа этого «да» не приняла (своего вопроса она не задавала) и
 * спросила согласие ещё раз, уже по форме. Человек дал согласие дважды.
 */
export function asksForConsent(text: string): boolean {
  return text.split(/(?<=[.!?\n])/).some((sentence) => CONSENT_ASK.test(sentence));
}

/**
 * Предложение, которое держится за вырезанное: «Оно нужно по закону…», «Без
 * него мы не можем…». Прогон на боевом снимке 10 октября: просьбу модели о
 * согласии вырезали, и пациент получил «Спасибо! Оно нужно по закону» — что
 * «оно», непонятно.
 */
const LEANS_ON_PREVIOUS = /^\s*(?:оно|оно\s+нужно|без\s+него|его|это\s+(?:нужно|требуется|стандартн)|так\s+мы|поэтому)(?!\p{L})/iu;

export function withoutConsentRequest(
  text: string,
  /**
   * Человек сам спросил, зачем согласие: объяснение модели оставляем, убираем
   * только вопросы («вы согласны?», «ответьте…»). Прогон на боевом снимке 10
   * октября: на «А зачем согласие?» уходило «…и оно используется только для
   * целей…» — начало объяснения вырезали как просьбу.
   */
  explaining = false,
): string {
  const parts = text.split(/(?<=[.!?\n])/);
  const dropped = parts.map(
    (sentence) =>
      CONSENT_ASK.test(sentence) &&
      (!explaining || /\?|(?<!\p{L})(?:ответьте|подтвердите|напишите|согласн\p{L}*\s+ли)(?!\p{L})/iu.test(sentence)),
  );
  return (
    parts
      .filter((sentence, i) => {
        if (dropped[i]) return false;
        /**
         * Хвосты просьбы о согласии, где бы они ни стояли: «Достаточно написать
         * „Согласен“ или „Согласна“», «Подписывается это один раз, при первом
         * визите» (прогон на боевом снимке, 10 октября). Без вырезанной просьбы
         * они бессмысленны, а с нашим запросом — второй запрос рядом.
         */
        if (
          dropped.some(Boolean) &&
          /(?:«|")\s*согласн\p{L}*|(?<!\p{L})достаточно\s+(?:написать|ответить)|(?<!\p{L})подписыва\p{L}*\s+(?:это\s+)?один\s+раз/iu.test(sentence)
        ) {
          dropped[i] = true;
          return false;
        }
        // Цепочка: за вырезанным идут одно-два предложения, держащиеся за него.
        let j = i - 1;
        while (j >= 0 && !parts[j].trim()) j -= 1;
        if (j >= 0 && dropped[j] && LEANS_ON_PREVIOUS.test(sentence)) {
          dropped[i] = true;
          return false;
        }
        return true;
      })
      .join("")
      /**
       * Ссылка на политику уходит вместе с просьбой.
       *
       * Просьбу вырезали, а строка «Политика: https://…» оставалась висеть
       * сама по себе: пациент получал голую ссылку без единого слова о том,
       * зачем она. На живом прогоне это выглядело так: цена, пустая строка,
       * ссылка на политику, и следом наш собственный запрос согласия.
       */
      .replace(/^[ \t]*политика(?:\s+здесь)?\s*:.*$/gim, "")
      .replace(/\n{3,}/g, "\n\n")
      .replace(/[ \t]{2,}/g, " ")
      .trim()
  );
}
